public class ExchangeRateClient {

    public class ExchangeRateException extends Exception {
    }

    private static final Pattern CURRENCY_CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        if (baseCurrency == null) {
            throw new ExchangeRateException('Base currency is required.');
        }

        String normalizedBase = baseCurrency.trim().toUpperCase();
        if (!isValidCurrencyCode(normalizedBase)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            if (quoteCurrency == null) {
                throw new ExchangeRateException('Invalid quote currency code: null');
            }
            String normalizedQuote = quoteCurrency.trim().toUpperCase();
            if (!isValidCurrencyCode(normalizedQuote)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + quoteCurrency);
            }
            normalizedQuotes.add(normalizedQuote);
        }

        if (normalizedQuotes.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency is required.');
        }

        List<String> sortedQuotes = new List<String>(normalizedQuotes);
        sortedQuotes.sort();
        String symbols = String.join(sortedQuotes, ',');

        String endpoint = 'callout:FB_Exchange_Rates/v1/latest'
            + '?base=' + normalizedBase
            + '&symbols=' + symbols;

        Http http = new Http();
        HttpResponse response = http.send(buildRequest(endpoint));

        if (response.getStatusCode() == 503) {
            response = http.send(buildRequest(endpoint));
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with status code ' + response.getStatusCode() + '.'
            );
        }

        return parseRates(response.getBody(), normalizedQuotes);
    }

    private static HttpRequest buildRequest(String endpoint) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return request;
    }

    private static Boolean isValidCurrencyCode(String code) {
        if (code == null || code.length() != 3) {
            return false;
        }
        Matcher matcher = CURRENCY_CODE_PATTERN.matcher(code);
        return matcher.matches();
    }

    private static Map<String, Decimal> parseRates(String body, Set<String> requestedCodes) {
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Failed to parse exchange rate response: empty body.');
        }

        try {
            Object parsedObject = JSON.deserializeUntyped(body);
            if (!(parsedObject instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Failed to parse exchange rate response: unexpected format.');
            }

            Map<String, Object> parsed = (Map<String, Object>) parsedObject;
            Object ratesObject = parsed.get('rates');
            if (!(ratesObject instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Failed to parse exchange rate response: missing rates.');
            }

            Map<String, Object> rates = (Map<String, Object>) ratesObject;
            Map<String, Decimal> result = new Map<String, Decimal>();

            for (String code : requestedCodes) {
                if (!rates.containsKey(code) || rates.get(code) == null) {
                    throw new ExchangeRateException('Missing exchange rate for currency: ' + code);
                }

                Object rateValue = rates.get(code);
                Decimal rate;

                if (rateValue instanceof Decimal) {
                    rate = (Decimal) rateValue;
                } else if (rateValue instanceof Integer) {
                    rate = Decimal.valueOf((Integer) rateValue);
                } else if (rateValue instanceof Long) {
                    rate = Decimal.valueOf((Long) rateValue);
                } else if (rateValue instanceof Double) {
                    rate = Decimal.valueOf((Double) rateValue);
                } else {
                    throw new ExchangeRateException('Invalid exchange rate for currency: ' + code);
                }

                result.put(code, rate);
            }

            return result;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Failed to parse exchange rate response: ' + e.getMessage());
        }
    }
}
