        assertQuote(25, 'DOMESTIC', true, 0, 32.63);  // 21.75 * 1.5 = 32.625
        assertQuote(29, 'DOMESTIC', true, 0, 37.13);  // 24.75 * 1.5 = 37.125
        assertQuote(33, 'DOMESTIC', true, 0, 41.63);  // 27.75 * 1.5 = 41.625
        assertQuote(23, 'EU', true, 0, 42.53);        // 20.25 * 1.4 * 1.5 = 42.525
        assertQuote(23, 'WORLD', true, 0, 66.83);     // 20.25 * 2.2 * 1.5 = 66.825
        assertQuote(27, 'EU', true, 0, 48.83);        // 23.25 * 1.4 * 1.5 = 48.825
        assertQuote(21, 'EU', true, 0, 39.38);        // 18.75 * 1.4 * 1.5 = 39.375
        assertQuote(21, 'WORLD', true, 0, 61.88);     // 18.75 * 2.2 * 1.5 = 61.875
        assertQuote(25, 'EU', true, 0, 45.68);        // 21.75 * 1.4 * 1.5 = 45.675
        assertQuote(25, 'WORLD', true, 0, 71.78);     // 21.75 * 2.2 * 1.5 = 71.775
        assertQuote(29, 'WORLD', true, 0, 81.68);     // 24.75 * 2.2 * 1.5 = 81.675
    }

    @isTest
    static void resultHasTwoDecimalPlacesScale() {
