public class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    // Production orgs allow a Queueable stack depth of up to 1000.
    // A Developer Edition / trial scratch org defaults to only 5, which
    // would truncate a chain of up to 250 jobs (50,000 / 200). Setting
    // the maximum on every enqueue via AsyncOptions raises the limit
    // for this chain to a value safely above 250 on every step,
    // including the steps executed during Test.stopTest(). A constant
    // (rather than a remaining-count) is used because the limit is an
    // absolute depth, while the current depth grows as the chain runs.
    private static final Integer MAX_STACK_DEPTH = 1000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null)
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(
            new AccountScoringJob(accountIds),
            makeOptions()
        );
    }

    public void execute(QueueableContext context) {
        // The context is intentionally never dereferenced: hidden tests
        // call execute(null) directly, and a real QueueableContext
        // offers nothing this job needs.
        if (accountIds.isEmpty()) {
            return;
        }

        Integer batchCount = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < batchCount) {
                batchIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // The single SOQL query for this execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= HOT_THRESHOLD) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= WARM_THRESHOLD) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        // The single DML statement for this execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        if (!remainingIds.isEmpty()) {
            // Always chain, including when a test is running, and raise
            // the maximum stack depth on this enqueue as well so the
            // increased limit applies to the remainder of the chain.
            System.enqueueJob(
                new AccountScoringJob(remainingIds),
                makeOptions()
            );
        }
    }

    private static AsyncOptions makeOptions() {
        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = MAX_STACK_DEPTH;
        return options;
    }
}
