public with sharing class Opportunities extends fflib_SObjectDomain {
    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void onValidate() {
        for (Opportunity record : (List<Opportunity>) Records) {
            validateAmountNotNegative(record);
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        for (Opportunity record : (List<Opportunity>) Records) {
            validateAmountNotNegative(record);

            Opportunity existingRecord = (Opportunity) existingRecords.get(record.Id);
            if (
                existingRecord != null &&
                existingRecord.StageName == 'Closed Won' &&
                record.Amount != existingRecord.Amount
            ) {
                record.Amount.addError(
                    error(
                        'Amount cannot change on a won opportunity.',
                        record,
                        Opportunity.Amount
                    )
                );
            }
        }
    }

    private void validateAmountNotNegative(Opportunity record) {
        if (record.Amount != null && record.Amount < 0) {
            record.Amount.addError(
                error('Amount cannot be negative.', record, Opportunity.Amount)
            );
        }
    }
}
