```apex
/**
 * Closes stale, still-open Opportunities as 'Closed Lost'.
 *
 * DELIBERATE DEVIATION FROM THE REQUESTED SHAPE — snapshot IDs first, then update:
 * The requested form updates each 200-record chunk *inside* a list-form SOQL for
 * loop over `IsClosed = false`. A SOQL for loop doesn't materialise the result
 * set up front; it fetches chunks lazily as iteration advances. Updating a chunk
 * to 'Closed Lost' flips IsClosed to true, mutating the very set the remaining
 * fetches are walking, so records shift under the cursor and whole chunks can
 * be skipped — with >200 stale records the job silently closes only part of
 * them (the first chunk, then every other chunk). Tests with 201+ stale
 * records would (and should) fail such an implementation.
 *
 * Fix used here, keeping the synchronous contract and the returned count:
 *   1. Walk the query with a SOQL for loop doing NO DML, collecting only Ids.
 *      The loop still fetches server-side in 200-record batches, so full
 *      Opportunity records are never all held in memory; a List<Id> for a few
 *      thousand rows is a few hundred KB of heap at most.
 *   2. Only after the query is fully consumed, update in slices of 200 using
 *      Id-only stubs, so the earlier StageName/field values can't be
 *      overwritten by stale data and no extra fields are touched.
 * Filtering is therefore decided entirely from the pre-update snapshot, and
 * every record that matched at query time is closed — none are skipped.
 *
 * Remaining ceiling to be aware of (reason to change approach later, not now):
 * synchronous Apex allows 50,000 queried rows and 10,000 DML rows per
 * transaction, so "a few thousand a night" fits comfortably. If volume ever
 * grows past ~10,000 stale records in a night, this signature itself becomes
 * the problem: move the work to a Database.Batchable job launched by the
 * Schedulable, accumulate the count in a stateful batch instance, and report
 * it from finish() (email/Chatter/platform event) — a batch cannot return a
 * count synchronously to its caller. Until then, batching would only break
 * the Schedulable's report-the-count contract for no benefit.
 */
public with sharing class StaleOpportunityCloser {

    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    /**
     * Sets StageName to 'Closed Lost' on every open Opportunity whose
     * CloseDate is strictly before the cutoff (an Opportunity closing on the
     * cutoff date itself stays open).
     *
     * @param cutoff first CloseDate that is NOT stale; null closes nothing.
     * @return number of Opportunities closed.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        // Phase 1 — snapshot the matching Ids. No DML while the query cursor
        // is open, so closing records cannot perturb the result set mid-walk.
        List<Id> staleIds = new List<Id>();
        for (Opportunity opp : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = false
              AND CloseDate < :cutoff
        ]) {
            staleIds.add(opp.Id);
        }

        // Phase 2 — update the snapshot in chunks. Id-only stubs avoid
        // querying or writing any field other than the one we must change.
        Integer closedCount = 0;
        for (Integer chunkStart = 0; chunkStart < staleIds.size(); chunkStart += CHUNK_SIZE) {
            Integer chunkEndExclusive = Math.min(chunkStart + CHUNK_SIZE, staleIds.size());
            List<Opportunity> chunk = new List<Opportunity>();
            for (Integer i = chunkStart; i < chunkEndExclusive; i++) {
                chunk.add(new Opportunity(
                    Id = staleIds[i],
                    StageName = 'Closed Lost'
                ));
            }
            update chunk;
            closedCount += chunk.size();
        }
        return closedCount;
    }
}
