public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static Boolean lastDayValueResolved = false;
    private static String lastDayOfMonthValue;

    /**
     * Returns the actual restricted-picklist API value for the
     * last-day-of-month option on npsp__Day_of_Month__c in this org,
     * discovered via Schema describe (no SOQL). The API value is not
     * 'Last Day' in current NPSP, so it must not be hard-coded.
     * Returns null if the picklist has no such entry, in which case
     * npsp__Always_Use_Last_Day_Of_Month__c alone carries the meaning.
     */
    private static String getLastDayOfMonthValue() {
        if (lastDayValueResolved) {
            return lastDayOfMonthValue;
        }
        lastDayValueResolved = true;
        lastDayOfMonthValue = null;

        Schema.DescribeFieldResult describe =
            npe03__Recurring_Donation__c.npsp__Day_of_Month__c.getDescribe();

        if (describe.getType() == Schema.DisplayType.Picklist ||
            describe.getType() == Schema.DisplayType.MultiPicklist) {
            for (Schema.PicklistEntry entry : describe.getPicklistValues()) {
                if (!entry.isActive()) {
                    continue;
                }
                String value = entry.getValue();
                String label = entry.getLabel();
                if ((value != null && value.toLowerCase().contains('last')) ||
                    (label != null && label.toLowerCase().contains('last'))) {
                    lastDayOfMonthValue = value;
                    break;
                }
            }
        } else {
            // Non-picklist fallback used by some NPSP versions.
            lastDayOfMonthValue = 'Last Day';
        }
        return lastDayOfMonthValue;
    }

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // Validate every request before any DML.
        for (GiftRequest request : requests) {
            if (request == null) {
                throw new RecurringGiftException('Gift request must not be null.');
            }
            if (request.contactId == null) {
                throw new RecurringGiftException('Contact is required.');
            }
            if (request.amount == null || request.amount <= 0) {
                throw new RecurringGiftException('Amount must be greater than zero.');
            }
            if (request.dayOfMonth == null || request.dayOfMonth < 1 || request.dayOfMonth > 31) {
                throw new RecurringGiftException('Day of month must be between 1 and 31.');
            }
            if (request.startDate == null) {
                throw new RecurringGiftException('Start date is required.');
            }
        }

        String lastDayValue = getLastDayOfMonthValue();

        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            Boolean isOpenEnded =
                request.installments == null || request.installments == 0;
            Boolean useLastDayOfMonth = request.dayOfMonth == 31;

            npe03__Recurring_Donation__c donation = new npe03__Recurring_Donation__c();
            donation.npe03__Contact__c = request.contactId;
            donation.npe03__Amount__c = request.amount;
            donation.npe03__Installment_Period__c = 'Monthly';
            donation.npe03__Schedule_Type__c = 'Multiply By';
            donation.npe03__Date_Established__c = request.startDate;
            donation.npe03__Next_Payment_Date__c = request.startDate;
            donation.npe03__Open_Ended_Status__c = isOpenEnded ? 'Open' : 'None';

            donation.npsp__RecurringType__c = isOpenEnded ? 'Open' : 'Fixed';
            donation.npsp__InstallmentFrequency__c = 1;
            if (useLastDayOfMonth) {
                // Use Enhanced Recurring Donations' own last-day-of-month
                // option: the org's actual picklist value (discovered via
                // describe, e.g. 'Last Day of Month') plus the
                // Always Use Last Day Of Month flag. 29/30 are stored
                // as those literal days, 31 is not.
                donation.npsp__Day_of_Month__c = lastDayValue;
                donation.npsp__Always_Use_Last_Day_Of_Month__c = true;
            } else {
                donation.npsp__Day_of_Month__c = String.valueOf(request.dayOfMonth);
                donation.npsp__Always_Use_Last_Day_Of_Month__c = false;
            }
            donation.npsp__StartDate__c = request.startDate;
            donation.npsp__Status__c = 'Active';
            donation.npsp__PaymentMethod__c = request.paymentMethod;

            if (!isOpenEnded) {
                donation.npe03__Installments__c = request.installments;
            }

            donations.add(donation);
        }

        // Single DML statement; NPSP Enhanced Recurring Donations
        // generates the installment Opportunities itself.
        insert donations;

        List<Id> donationIds = new List<Id>();
        for (npe03__Recurring_Donation__c donation : donations) {
            donationIds.add(donation.Id);
        }
        return donationIds;
    }
}
