public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        // Respect object-level read access: return no records if the
        // running user cannot read the object at all.
        Schema.DescribeSObjectResult employeeDescribe = FB_Employee__c.SObjectType.getDescribe();

        if (!employeeDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Always select Id and Name. Conditionally select each custom
        // field only when the running user has field-level read access,
        // so inaccessible fields are never queried and are absent
        // (not merely null) on the returned records. This also prevents
        // the query from throwing for users with partial FLS access.
        List<String> selectFields = new List<String>{ 'Id', 'Name' };

        if (FB_Employee__c.Department__c.getDescribe().isAccessible()) {
            selectFields.add('Department__c');
        }
        if (FB_Employee__c.Salary__c.getDescribe().isAccessible()) {
            selectFields.add('Salary__c');
        }
        if (FB_Employee__c.Personal_Email__c.getDescribe().isAccessible()) {
            selectFields.add('Personal_Email__c');
        }

        // Field names are a fixed whitelist derived from describe calls,
        // so there is no injection risk in the constructed query.
        // Record-level sharing is enforced by the `with sharing` class
        // context, which applies to dynamic SOQL as well. FLS is not
        // enforced by SOQL itself, hence the explicit checks above
        // (and no WITH SECURITY_ENFORCED, which would throw for
        // users lacking access to any queried field).
        String soql =
            'SELECT ' + String.join(selectFields, ', ') +
            ' FROM FB_Employee__c' +
            ' ORDER BY Name ASC';

        return (List<FB_Employee__c>) Database.query(soql);
    }
}
